def parse_age(text):
    try:
        age = int(text)
    except ValueError:
        return None
    if age < 0:
        raise ValueError("age cannot be negative")
    return age

print(parse_age("42"))   # 42
print(parse_age("abc"))  # None

class InsufficientFunds(Exception):
    pass

try:
    raise InsufficientFunds("balance too low")
except InsufficientFunds as error:
    print("failed:", error)     # failed: balance too low
else:
    print("no error")
finally:
    print("done")               # always printed
